import{i as e}from"./busy.CCp4wE9r.js";import{n as t,t as n}from"./image-ready.yaTrNC1F.js";import{n as r,r as i,t as a}from"./cards.BVIR-fFN.js";import{t as o}from"./masters.CD7Lf9y9.js";import{a as s,c,i as l,l as u,n as d,o as f,s as p,t as m,u as h}from"./categories.CDw9ZhQp.js";import{n as g,t as ee}from"./verdict.B9lKvcSp.js";import{R as _,h as v,j as y,z as b}from"./chinipy-account.CTJFevOc.js";import{u as te}from"./account-consent.MBot3WoA.js";import{C as ne,D as re,L as ie,M as x,N as ae,P as oe,V as se,b as ce,h as le,j as ue,l as de,m as S,n as fe,u as pe,w as me,z as he}from"./reading-api.D-_5b4S_.js";import{r as ge}from"./paths.4BZngo9B.js";import{n as C,t as _e}from"./analytics.DOoVvihR.js";import{t as ve}from"./preload-helper.khBccGFq.js";import{C as ye,S as be,T as xe,_ as Se,c as Ce,d as we,f as Te,i as Ee,l as De,n as Oe,p as ke,s as Ae,u as je,w as Me,y as Ne}from"./guest.Bh7fFrLz.js";import{i as Pe,n as Fe,r as Ie,s as Le}from"./share-images.DVm8c6qD.js";import{A as Re,C as ze,D as w,E as Be,F as Ve,I as He,L as Ue,M as We,N as Ge,O as Ke,P as qe,S as Je,T as Ye,U as Xe,_ as Ze,a as Qe,b as $e,c as et,d as tt,f as nt,g as rt,h as it,i as at,j as ot,k as st,l as ct,m as lt,n as ut,o as dt,p as ft,r as pt,s as mt,t as ht,u as gt,v as _t,w as vt,x as yt,y as bt}from"./push.CQhooVNK.js";import{i as xt}from"./reward-check.DmWKOgD4.js";import{n as St,r as Ct}from"./type-test.oXDjm3pL.js";import{a as wt,i as Tt,n as Et,r as Dt,t as Ot}from"./kakao.D2sfRqb-.js";import{a as kt,c as At,i as jt,n as Mt,o as Nt,s as Pt}from"./share.DqH5ImjS.js";import{t as Ft}from"./benefits-summary.BxNn_jvQ.js";import{n as It}from"./recent-apps.ChBISNrp.js";import{t as Lt}from"./launcher-home.BORue4jo.js";import{a as Rt,r as zt}from"./live-state.CgVPKuGa.js";var Bt={major:`메이저 아르카나 · 인생의 큰 흐름`,wand:`완드 · 열정과 행동`,cup:`컵 · 감정과 관계`,sword:`검 · 생각과 결단`,coin:`동전 · 돈과 현실`},Vt={0:{upright:`두려움 없이 새로운 길에 첫발을 내딛는 카드예요. 계산보다 설렘을 믿어 볼 때예요.`,reversed:`준비 없이 뛰어들거나 망설이다 기회를 놓치기 쉬운 때예요. 발밑을 한 번 살펴보세요.`},1:{upright:`필요한 재능과 도구가 이미 손안에 있다는 카드예요. 생각을 실제 행동으로 옮길 때예요.`,reversed:`능력을 제대로 쓰지 못하거나 말과 행동이 엇갈리기 쉬운 때예요. 목표를 다시 또렷하게 잡아 보세요.`},2:{upright:`겉으로 드러나지 않은 답을 직관이 알고 있다는 카드예요. 조용히 마음의 소리에 귀 기울여 보세요.`,reversed:`감을 믿지 못하거나 감춰진 사실이 흐름을 흐리는 때예요. 서두르지 말고 정보를 더 모아 보세요.`},3:{upright:`사랑과 돌봄 속에서 무언가가 풍성하게 자라나는 카드예요. 여유를 갖고 가꾸면 열매를 맺어요.`,reversed:`남을 챙기느라 나를 돌보지 못했거나 의욕이 시든 때예요. 스스로를 먼저 채워 주세요.`},4:{upright:`원칙과 계획으로 상황을 단단히 세우는 카드예요. 주도권을 쥐고 책임 있게 이끌어 갈 때예요.`,reversed:`고집이나 통제가 지나쳐 마찰이 생기기 쉬운 때예요. 규칙에 숨 쉴 틈을 남겨 두세요.`},5:{upright:`검증된 방법과 믿을 만한 조언이 길잡이가 되는 카드예요. 배움과 전통에서 답을 찾을 수 있어요.`,reversed:`틀에 박힌 방식이 오히려 발목을 잡는 때예요. 나에게 맞는 방식을 새로 찾아보세요.`},6:{upright:`마음이 통하는 관계와 진심이 담긴 선택을 뜻하는 카드예요. 가치관이 맞는 쪽을 고르세요.`,reversed:`마음이 엇갈리거나 선택 앞에서 흔들리는 때예요. 내가 정말 원하는 것부터 정리해 보세요.`},7:{upright:`강한 의지로 장애물을 넘고 앞으로 나아가는 카드예요. 방향을 정했다면 힘차게 밀고 가세요.`,reversed:`의욕은 큰데 방향이 흩어져 제자리걸음하기 쉬운 때예요. 고삐를 다시 잡아 보세요.`},8:{upright:`뿌린 대로 거두는 공정한 결과를 뜻하는 카드예요. 사실에 근거해 균형 있게 판단할 때예요.`,reversed:`한쪽으로 치우친 판단이나 억울한 일이 생기기 쉬운 때예요. 감정보다 사실을 확인해 보세요.`},9:{upright:`잠시 물러나 내면을 비추며 답을 찾는 카드예요. 혼자만의 시간이 오히려 길을 밝혀 줘요.`,reversed:`고립감이 커지거나 생각에 갇히기 쉬운 때예요. 믿을 만한 사람과 이야기를 나눠 보세요.`},10:{upright:`운의 흐름이 바뀌는 전환점을 뜻하는 카드예요. 다가오는 변화에 올라타 보세요.`,reversed:`타이밍이 잘 맞지 않거나 같은 일이 되풀이되는 때예요. 흐름이 바뀔 때까지 차분히 준비하세요.`},11:{upright:`부드럽지만 꺾이지 않는 용기를 뜻하는 카드예요. 힘보다 인내와 다정함이 상황을 다스려요.`,reversed:`자신감이 흔들리거나 감정이 앞서기 쉬운 때예요. 숨을 고르고 나를 다독여 주세요.`},12:{upright:`잠시 멈춰 다른 각도에서 보면 답이 보이는 카드예요. 기다림이 깨달음으로 이어져요.`,reversed:`의미 없이 미루거나 희생만 계속되는 때예요. 멈춤을 끝내고 결정할 때가 왔는지 살펴보세요.`},13:{upright:`하나가 끝나야 새로운 것이 시작된다는 카드예요. 낡은 것을 정리하면 새 장이 열려요.`,reversed:`끝내야 할 것을 붙잡고 변화를 미루는 때예요. 놓아야 할 것을 하나씩 내려놓아 보세요.`},14:{upright:`서로 다른 것을 알맞게 섞어 조화를 이루는 카드예요. 서두르지 않는 꾸준함이 치유가 돼요.`,reversed:`균형이 깨져 한쪽으로 쏠리기 쉬운 때예요. 생활 리듬과 마음의 중심을 다시 맞춰 보세요.`},15:{upright:`알면서도 끊기 어려운 집착과 유혹을 비추는 카드예요. 나를 묶는 것이 무엇인지 들여다보세요.`,reversed:`얽매임에서 벗어날 실마리가 보이는 때예요. 작은 것부터 스스로 사슬을 풀어 보세요.`},16:{upright:`예상 못 한 변화가 낡은 틀을 무너뜨리는 카드예요. 흔들림 뒤에 진짜 기반이 드러나요.`,reversed:`피하고 싶은 변화를 버티며 미루는 때예요. 작게라도 먼저 바꾸면 충격이 줄어요.`},17:{upright:`어둠 뒤에 찾아오는 희망과 치유의 카드예요. 마음을 열고 앞날을 믿어 봐도 좋아요.`,reversed:`기대가 꺾여 의욕을 잃기 쉬운 때예요. 작은 희망 하나부터 다시 붙잡아 보세요.`},18:{upright:`분명하지 않은 상황과 마음속 불안을 비추는 카드예요. 보이는 것만 믿지 말고 천천히 살피세요.`,reversed:`안개가 걷히며 헷갈리던 일이 드러나는 때예요. 막연한 두려움을 하나씩 확인해 보세요.`},19:{upright:`기쁨과 성공이 환하게 비추는 카드예요. 자신 있게 나서면 좋은 결과가 따라와요.`,reversed:`기쁨이 잠시 구름에 가려진 때예요. 지나친 낙관이나 의심을 덜고 작은 성취를 즐겨 보세요.`},20:{upright:`지난 일을 돌아보고 새롭게 깨어나는 카드예요. 망설이던 결정을 내릴 때가 왔어요.`,reversed:`자책이나 미련이 발목을 잡는 때예요. 지난 일을 받아들이고 스스로를 용서해 주세요.`},21:{upright:`한 여정이 완성되고 결실을 맺는 카드예요. 이룬 것을 축하하고 다음 무대를 준비하세요.`,reversed:`마무리가 조금 덜 된 채 머무는 때예요. 남은 한 조각을 채우면 완성이 보여요.`},22:{upright:`감정에 휘둘리지 않는 명확한 판단의 카드예요. 사실과 원칙으로 결정을 내리세요.`,reversed:`냉정함이 지나쳐 차갑게 비치거나 판단이 흐려지는 때예요. 논리에 배려를 더해 보세요.`},23:{upright:`흐릿한 것을 꿰뚫어 보는 예리한 통찰의 카드예요. 솔직하고 분명하게 말해도 좋아요.`,reversed:`날카로운 말이 상처가 되기 쉬운 때예요. 판단은 분명히, 말은 부드럽게 해 보세요.`},24:{upright:`목표를 향해 거침없이 돌진하는 카드예요. 빠른 결단이 돌파구를 열어 줘요.`,reversed:`서두르다 실수하거나 말이 앞서기 쉬운 때예요. 한 박자 늦추고 계획을 점검하세요.`},25:{upright:`호기심 가득한 눈으로 새 정보를 살피는 카드예요. 질문하고 배우면 기회가 보여요.`,reversed:`소문이나 섣부른 말에 휘둘리기 쉬운 때예요. 확인된 정보만 믿으세요.`},26:{upright:`복잡하던 일이 한 번에 정리되는 깨달음의 카드예요. 새 아이디어가 돌파구가 돼요.`,reversed:`생각이 엉키거나 판단이 흐려지는 때예요. 핵심 하나만 남기고 정리해 보세요.`},27:{upright:`두 갈래 길 앞에서 잠시 판단을 미루는 카드예요. 눈가리개를 벗고 정보를 더 모으세요.`,reversed:`미뤄 둔 결정이 더는 기다려 주지 않는 때예요. 완벽하지 않아도 하나를 골라 보세요.`},28:{upright:`마음 아픈 일이나 이별의 상처를 비추는 카드예요. 슬픔을 인정해야 치유가 시작돼요.`,reversed:`상처가 서서히 아물어 가는 때예요. 지난 아픔을 조금씩 흘려보내 보세요.`},29:{upright:`지친 몸과 마음을 쉬게 하라는 카드예요. 잠시 멈추면 다시 나아갈 힘이 생겨요.`,reversed:`쉬어야 할 때 쉬지 못했거나 이제 다시 움직일 때예요. 회복 정도를 솔직히 살펴보세요.`},30:{upright:`이겨도 남는 게 없는 다툼을 비추는 카드예요. 이길 싸움과 내려놓을 싸움을 가려 보세요.`,reversed:`갈등이 잦아들고 화해할 틈이 보이는 때예요. 먼저 한 발 물러서도 괜찮아요.`},31:{upright:`힘든 곳을 벗어나 잔잔한 쪽으로 옮겨 가는 카드예요. 천천히라도 나아지고 있어요.`,reversed:`떠나야 할 곳에서 발이 잘 떨어지지 않는 때예요. 짐을 줄이면 이동이 가벼워져요.`},32:{upright:`정면 대신 우회로를 고르는 전략의 카드예요. 계획은 조용히, 행동은 신중하게 하세요.`,reversed:`감춰 둔 일이 드러나거나 꾀가 통하지 않는 때예요. 솔직함이 가장 좋은 전략이에요.`},33:{upright:`스스로 만든 생각의 틀에 갇힌 카드예요. 매듭은 생각보다 느슨하니 한 걸음만 내디뎌 보세요.`,reversed:`답답함이 풀리고 출구가 보이기 시작하는 때예요. 도움을 청하면 더 빨리 벗어나요.`},34:{upright:`밤잠을 설칠 만큼 걱정이 큰 카드예요. 머릿속 걱정을 글로 적으면 크기가 줄어들어요.`,reversed:`최악의 걱정이 조금씩 옅어지는 때예요. 혼자 끌어안지 말고 털어놓아 보세요.`},35:{upright:`바닥을 쳤기에 이제 올라갈 일만 남은 카드예요. 끝을 받아들이면 새벽이 와요.`,reversed:`가장 힘든 고비를 지나 회복이 시작되는 때예요. 같은 상처를 반복하지 않게 돌아보세요.`},36:{upright:`큰 그림을 그리고 사람들을 이끄는 리더의 카드예요. 비전을 믿고 앞장서 보세요.`,reversed:`의욕이 지나쳐 독단이 되기 쉬운 때예요. 주변의 의견에도 귀를 열어 보세요.`},37:{upright:`당당한 자신감과 따뜻한 매력의 카드예요. 나답게 빛나면 사람과 기회가 모여요.`,reversed:`자신감이 흔들리거나 질투에 마음이 쓰이는 때예요. 남보다 나의 속도에 집중하세요.`},38:{upright:`열정을 안고 새로운 도전에 뛰어드는 카드예요. 지금의 추진력을 놓치지 마세요.`,reversed:`충동적으로 움직이다 금세 지치기 쉬운 때예요. 열정을 오래 태울 계획을 세워 보세요.`},39:{upright:`가슴 뛰는 새 아이디어나 소식이 찾아오는 카드예요. 작은 시도부터 시작해 보세요.`,reversed:`시작은 했는데 방향을 잡지 못한 때예요. 하고 싶은 것 하나에 먼저 집중해 보세요.`},40:{upright:`새로운 열정과 영감에 불이 붙는 카드예요. 떠오른 아이디어를 바로 행동으로 옮겨 보세요.`,reversed:`불씨는 있는데 타오르지 못하는 때예요. 미루던 첫 단계를 오늘 시작해 보세요.`},41:{upright:`더 넓은 세상을 바라보며 계획을 세우는 카드예요. 익숙한 곳을 넘어설 준비를 하세요.`,reversed:`계획만 세우고 떠나지 못하는 때예요. 두려움보다 가능성을 따져 보세요.`},42:{upright:`준비한 일이 결실을 향해 뻗어 나가는 카드예요. 더 멀리 내다보고 기회를 넓혀 보세요.`,reversed:`기다리던 소식이 늦어지는 때예요. 조급해하지 말고 다른 길도 열어 두세요.`},43:{upright:`함께 축하할 일이 생기는 기쁨의 카드예요. 안정된 기반 위에서 사람들과 즐겨 보세요.`,reversed:`들뜬 분위기 속에 작은 불안이 섞인 때예요. 가까운 관계부터 다독여 보세요.`},44:{upright:`서로 다른 의견이 부딪히는 경쟁의 카드예요. 다툼도 성장의 자극으로 쓸 수 있어요.`,reversed:`소모적인 다툼을 피하거나 갈등이 정리되는 때예요. 공통의 목표를 찾아보세요.`},45:{upright:`노력을 인정받고 박수받는 승리의 카드예요. 성과를 자랑스럽게 드러내도 좋아요.`,reversed:`인정받지 못해 서운하거나 자만하기 쉬운 때예요. 남의 평가보다 내 기준을 믿으세요.`},46:{upright:`지켜야 할 것을 위해 꿋꿋이 맞서는 카드예요. 내 자리와 신념을 당당히 지키세요.`,reversed:`혼자 모든 것을 막아 내느라 지친 때예요. 물러설 곳과 지킬 곳을 구분해 보세요.`},47:{upright:`막혀 있던 일이 빠르게 움직이는 카드예요. 좋은 소식이 연달아 들어올 수 있어요.`,reversed:`속도가 너무 빨라 헛디디거나 일이 지연되는 때예요. 우선순위를 다시 정해 보세요.`},48:{upright:`지쳤지만 결승선이 바로 앞인 카드예요. 마지막 고비만 버티면 지켜 낼 수 있어요.`,reversed:`경계가 지나쳐 마음이 지친 때예요. 혼자 버티지 말고 도움을 받아 보세요.`},49:{upright:`너무 많은 짐을 혼자 짊어진 카드예요. 목표는 가까우니 덜어 낼 것을 찾아보세요.`,reversed:`버티기 힘든 무게를 내려놓을 때예요. 맡기고 거절하는 것도 능력이에요.`},50:{upright:`노력이 든든한 재정과 신뢰로 돌아오는 카드예요. 안정된 판단이 풍요를 지켜 줘요.`,reversed:`돈과 성과에 지나치게 매달리기 쉬운 때예요. 숫자 너머의 가치도 돌아보세요.`},51:{upright:`실속 있게 챙기며 주변을 따뜻하게 돌보는 카드예요. 생활의 작은 여유가 행복이 돼요.`,reversed:`남을 챙기느라 내 몫을 잃거나 생활이 흐트러진 때예요. 나를 위한 돌봄도 챙기세요.`},52:{upright:`느리지만 확실하게 나아가는 성실함의 카드예요. 꾸준함이 결국 결과를 만들어요.`,reversed:`반복에 지치거나 지나치게 신중해 멈춰 선 때예요. 작은 변화로 리듬을 깨워 보세요.`},53:{upright:`배우고 익히며 현실적인 첫걸음을 떼는 카드예요. 작은 기회도 성실히 붙잡아 보세요.`,reversed:`계획만 있고 실천이 따라오지 않는 때예요. 오늘 할 수 있는 일부터 시작하세요.`},54:{upright:`물질적인 행운의 씨앗이 손에 들어오는 카드예요. 잘 심고 가꾸면 번영으로 자라요.`,reversed:`들어온 기회를 놓치거나 지출이 새기 쉬운 때예요. 계획 없는 소비를 점검해 보세요.`},55:{upright:`여러 일을 유연하게 굴려 가는 균형의 카드예요. 바쁘지만 리듬을 타면 잘 해낼 수 있어요.`,reversed:`감당할 일이 넘쳐 균형이 흔들리는 때예요. 지금 꼭 할 일만 남겨 보세요.`},56:{upright:`함께 손발을 맞추며 실력을 인정받는 카드예요. 협업이 결과의 완성도를 높여 줘요.`,reversed:`팀워크가 삐걱거리거나 노력이 드러나지 않는 때예요. 역할과 기대를 분명히 나눠 보세요.`},57:{upright:`가진 것을 지키려 단단히 움켜쥔 카드예요. 안정은 좋지만 너무 꽉 쥐면 흐름이 막혀요.`,reversed:`지나친 통제를 풀거나 반대로 씀씀이가 헤퍼지는 때예요. 지킬 것과 쓸 것을 나눠 보세요.`},58:{upright:`어렵고 외로운 시기를 비추는 카드예요. 가까이에 도움의 손길이 있으니 문을 두드려 보세요.`,reversed:`힘든 시기가 지나가고 회복이 시작되는 때예요. 받은 도움을 기억하며 다시 일어서 보세요.`},59:{upright:`주고받음이 균형을 이루는 나눔의 카드예요. 베푼 만큼 돌아오는 흐름이에요.`,reversed:`한쪽만 주거나 받는 관계가 되기 쉬운 때예요. 조건 붙은 호의는 경계하세요.`},60:{upright:`지금까지의 노력을 돌아보며 수확을 기다리는 카드예요. 조금 더 기다리면 열매가 익어요.`,reversed:`노력에 비해 결과가 더디게 느껴지는 때예요. 방향이 맞는지 점검하고 방법을 바꿔 보세요.`},61:{upright:`한 가지를 깊게 파고드는 장인정신의 카드예요. 반복 연습이 실력이 되는 시기예요.`,reversed:`일이 기계적으로 느껴지거나 완벽주의에 지친 때예요. 왜 시작했는지 떠올려 보세요.`},62:{upright:`스스로 일군 풍요를 여유롭게 누리는 카드예요. 노력한 나에게 보상을 줘도 좋아요.`,reversed:`겉으로는 풍요로워도 속이 허전한 때예요. 진짜 독립이 무엇인지 생각해 보세요.`},63:{upright:`가족과 공동체가 오래 누릴 안정의 카드예요. 길게 보는 선택이 든든한 유산이 돼요.`,reversed:`돈이나 가족 문제로 마찰이 생기기 쉬운 때예요. 당장의 이익보다 관계를 먼저 챙기세요.`},64:{upright:`감정의 파도 속에서도 중심을 지키는 카드예요. 너그러운 마음이 주변을 안정시켜요.`,reversed:`감정을 억누르다 한꺼번에 흔들리기 쉬운 때예요. 마음을 건강하게 표현해 보세요.`},65:{upright:`상대의 마음을 깊이 헤아리는 공감의 카드예요. 직관과 따뜻함이 좋은 길잡이가 돼요.`,reversed:`남의 감정까지 떠안아 지친 때예요. 마음의 경계선을 정해 나를 지켜 주세요.`},66:{upright:`설레는 마음과 낭만적인 제안이 다가오는 카드예요. 마음을 표현하기 좋은 때예요.`,reversed:`기대가 너무 커서 현실과 어긋나기 쉬운 때예요. 말보다 행동을 지켜보세요.`},67:{upright:`순수한 감성과 새로운 감정이 피어나는 카드예요. 작은 설렘과 영감을 반겨 보세요.`,reversed:`감정이 서툴게 표현되거나 상처받기 쉬운 때예요. 마음을 조금 더 다독여 주세요.`},68:{upright:`마음이 차오르며 새로운 사랑과 기쁨이 시작되는 카드예요. 감정을 아낌없이 나눠 보세요.`,reversed:`마음이 닫혔거나 감정을 쏟을 곳을 찾지 못한 때예요. 나를 먼저 아껴 주세요.`},69:{upright:`두 마음이 서로 통하고 연결되는 카드예요. 진심을 주고받으면 관계가 깊어져요.`,reversed:`오해나 엇갈림으로 거리가 생기기 쉬운 때예요. 먼저 솔직하게 대화를 열어 보세요.`},70:{upright:`좋은 사람들과 기쁨을 나누는 축하의 카드예요. 모임과 우정이 힘이 돼요.`,reversed:`어울림이 지나치거나 관계 속에서 소외감을 느끼는 때예요. 나에게 맞는 거리를 찾아보세요.`},71:{upright:`익숙함에 지루해져 눈앞의 기회를 놓치기 쉬운 카드예요. 고개를 들어 주변을 둘러보세요.`,reversed:`무기력에서 벗어나 다시 관심이 생기는 때예요. 새 제안에 마음을 열어 보세요.`},72:{upright:`잃은 것에 대한 아쉬움이 큰 카드예요. 뒤를 돌아보면 아직 남은 희망이 있어요.`,reversed:`실망을 털고 다시 일어서는 때예요. 남은 것에 집중하면 마음이 가벼워져요.`},73:{upright:`따뜻한 추억과 순수한 마음을 떠올리게 하는 카드예요. 반가운 재회가 있을 수 있어요.`,reversed:`과거에 머물러 지금을 놓치기 쉬운 때예요. 추억은 간직하고 시선은 앞으로 두세요.`},74:{upright:`여러 선택지와 기대가 한꺼번에 떠오르는 카드예요. 환상과 현실을 차분히 가려내세요.`,reversed:`흐릿하던 선택지가 정리되며 답이 보이는 때예요. 현실적인 것 하나를 골라 보세요.`},75:{upright:`더는 마음이 머물지 않는 곳을 떠나는 카드예요. 아쉬워도 새로운 길을 찾아 나설 때예요.`,reversed:`떠날지 머물지 망설이는 때예요. 두려움 때문인지 미련 때문인지 살펴보세요.`},76:{upright:`바라던 소원이 이루어지는 만족의 카드예요. 지금의 행복을 마음껏 누려 보세요.`,reversed:`바라던 것을 얻어도 채워지지 않는 느낌이 드는 때예요. 진짜 원하는 것을 다시 물어보세요.`},77:{upright:`사랑하는 사람들과 함께 누리는 충만한 행복의 카드예요. 마음이 편안해지는 흐름이에요.`,reversed:`가까운 관계에 작은 금이 가기 쉬운 때예요. 기대보다 고마움을 먼저 전해 보세요.`}},Ht={major:{scene:``,notInArt:[]},sword:{scene:`검 수트는 흰 토끼들이 구름 위나 성, 바닷가를 배경으로 검을 든다`,notInArt:[]},wand:{scene:`완드 수트는 주로 검은 고양이가 사막과 사막 마을을 배경으로 끝에 붉은 구슬이 달린 지팡이를 든다`,notInArt:[]},coin:{scene:`동전 수트는 동전 대신 새싹이 자라는 화분을 호랑이들이 정글이나 정원을 배경으로 든다`,notInArt:[`손에 든 동전`,`금화`]},cup:{scene:`컵 수트는 개구리들이 수련이 뜬 물가를 배경으로 금잔을 든다`,notInArt:[]}},Ut={0:{scene:`조끼 입은 개구리가 막대 끝 보따리를 어깨에 메고 흰 꽃 한 송이를 든 채 물가 절벽 끝에서 한 발을 내딛는다. 하늘에 큰 해가 뜨고 나비가 날며, 아래 물에 수련잎이 떠 있다`,notInArt:[`개`]},1:{scene:`붉은 망토의 검은 고양이가 한 손에 지팡이를 높이 들고 다른 손은 아래를 가리킨다. 머리 위에 무한대 기호, 뒤로 장미와 백합 아치가 있고, 탁자 위에 검·붉은 구슬 지팡이·금잔·새싹 화분이 놓여 있다`,notInArt:[`오각별 원반`]},2:{scene:`초승달 관을 쓴 흰 토끼가 별 무늬 남색 로브를 입고 B 글자 검은 기둥과 J 글자 흰 기둥 사이에 앉아 두루마리를 펼쳐 든다. 뒤에 석류 휘장과 물, 위에 초승달이 있다`,notInArt:[]},3:{scene:`별 왕관을 쓴 호랑이가 초록 드레스를 입고 홀을 든 채 밀밭 속 돌 왕좌에 앉아 있다. 발치에 금성 기호가 새겨진 하트 방패, 뒤로 숲과 폭포가 있다`,notInArt:[]},4:{scene:`왕관 쓴 흰 토끼가 붉은 망토를 두르고 숫양 머리 장식 돌 왕좌에 앉아 한 손에 앙크 홀, 다른 손에 황금 구슬을 든다. 뒤로 붉은 바위산과 강이 있다`,notInArt:[]},5:{scene:`십자 무늬 주교관을 쓴 검은 고양이가 한 손을 들고 돌 왕좌에 앉아 있고, 왕좌 앞에 교차한 열쇠 두 개가 새겨져 있다. 앞에서 흰 옷의 호랑이와 개구리가 무릎 꿇고 있고, 뒤로 돌기둥과 스테인드글라스 창이 있다`,notInArt:[`삼중 십자 지팡이`]},6:{scene:`옷 입은 호랑이와 개구리가 숲속에서 서로 손을 맞잡고 있다. 왼쪽에 사과가 열린 나무, 오른쪽에 불꽃이 핀 나무가 있고, 위 구름 사이로 날개 달린 해가 빛난다`,notInArt:[`벌거벗은 남녀`,`뱀`,`천사`]},7:{scene:`별 왕관을 쓴 검은 고양이가 별 무늬 천개 아래 노란 전차에 서서 붉은 구슬 지팡이를 들고 있다. 앞에 흰 고양이와 검은 고양이가 앉아 있고, 뒤로 주황빛 하늘 아래 성탑과 마을이 있다`,notInArt:[`흑백 스핑크스`]},8:{scene:`흰 토끼가 기둥 사이 돌 왕좌에 앉아 한 손에 곧게 세운 검, 다른 손에 저울을 든다`,notInArt:[]},9:{scene:`두건 달린 회색 망토의 토끼가 별과 초승달이 뜬 어두운 하늘 아래 눈 덮인 산꼭대기에 서서 육각별 등불과 지팡이를 든다`,notInArt:[]},10:{scene:`구름 속에 별자리 기호가 새겨진 큰 금빛 바퀴가 있고, 네 귀퉁이 구름 위에 책을 든 흰 토끼·검은 고양이·호랑이·잔을 든 개구리가 앉아 있다`,notInArt:[`스핑크스`,`뱀`,`아누비스`]},11:{scene:`꽃관을 쓴 흰 옷의 개구리가 앉아 있는 호랑이의 얼굴을 부드럽게 쓰다듬는다. 위에 무한대 기호, 뒤로 꽃이 핀 들판과 산 너머 해가 있다`,notInArt:[`사자`]},12:{scene:`개구리가 나뭇가지에 밧줄로 발이 묶여 거꾸로 매달려 있고, 머리 둘레가 환하게 빛난다. 아래에 수련이 핀 연못, 뒤로 야자수가 있다`,notInArt:[`T자 나무`]},13:{scene:`검은 갑옷에 두건을 쓴 호랑이 기사가 흰 장미 무늬 검은 깃발을 들고 흰 말을 타고 물가를 지나간다. 멀리 두 탑 사이로 해가 떠오른다`,notInArt:[`해골`,`쓰러진 왕과 사람들`]},14:{scene:`날개 달린 흰 옷의 개구리가 물가에 서서 위 잔의 물을 아래 잔으로 옮겨 붓는다. 가슴에 세모 표식이 있고, 옆에 노란 붓꽃, 뒤로 길이 이어진 산 위에 왕관과 해가 있다`,notInArt:[`이마의 태양 표식`]},15:{scene:`숫양 뿔과 박쥐 날개가 달린 흰 토끼가 검은 로브를 입고 횃불을 든 채 돌 받침대 위에 앉아 있다. 발치에 호랑이와 개구리가 목에 줄이 묶인 채 서 있고, 뒤로 용암이 흐르는 동굴과 화산이 있다`,notInArt:[`염소 머리 악마`,`거꾸로 된 별`,`벌거벗은 남녀`]},16:{scene:`바위산 위 돌탑이 번개를 맞아 불타고, 떨어지는 왕관 옆으로 호랑이 한 마리가 구름 쪽으로 떨어진다. 하늘은 어둡고 아래에 바람에 휜 야자수가 있다`,notInArt:[]},17:{scene:`밤하늘 큰 팔각별과 작은 별들 아래 개구리가 물가에 앉아 두 손의 주전자로 연못과 땅에 물을 붓는다. 뒤로 야자수와 언덕 위 작은 새, 물 위에 수련이 있다`,notInArt:[`벌거벗은 여인`]},18:{scene:`얼굴이 그려진 초승달 아래 갈색 두건 망토의 검은 고양이가 두 탑 사이 굽이진 사막 길을 걷는다. 앞쪽 웅덩이에 가재 한 마리가 있다`,notInArt:[`개`,`늑대`]},19:{scene:`붉은 띠를 두른 아기 호랑이가 커다란 해 아래 해바라기 핀 돌담 앞에서 해바라기 한 송이를 들고 손을 흔들며 뛰논다`,notInArt:[`백마`,`붉은 깃발`,`구름`,`성`]},20:{scene:`날개 달린 흰 토끼가 빛나는 구름 사이에서 십자 깃발이 달린 나팔을 불고, 아래 물속에서 호랑이·검은 고양이·개구리가 두 손을 들어 올린다`,notInArt:[`천사 가브리엘`,`벌거벗은 사람들`,`관`]},21:{scene:`보라 띠를 두른 흰 토끼가 두 손에 막대를 하나씩 들고 붉은 리본으로 묶인 월계관 고리 안에서 춤춘다. 네 귀퉁이에 흰 토끼·검은 고양이·개구리·호랑이 얼굴이 있다`,notInArt:[`천사·독수리·사자·황소`]},22:{scene:`왕관 쓴 토끼 왕이 화려한 망토를 두르고 구름 위 성을 배경으로 왕좌에 앉아 검을 세워 든다`,notInArt:[`나비 문양 왕좌`]},23:{scene:`나비 왕관을 쓴 토끼 여왕이 털 장식 파란 망토를 두르고 구름 위 돌 왕좌에 앉아 한 손에 검을 곧게 세워 들고 다른 손을 들어 올린다. 뒤로 성탑과 날아가는 새들, 초승달이 있다`,notInArt:[]},24:{scene:`갑옷 입은 토끼 기사가 검을 치켜들고 흰 말을 타고 구름 위를 달린다. 뒤로 성이 보인다`,notInArt:[`폭풍에 휘는 나무`]},25:{scene:`깃털 모자를 쓴 토끼 시종이 구름 위로 솟은 바위에 서서 두 손으로 검 한 자루를 비스듬히 쥐고 있다. 바람에 나뭇잎이 날리고, 하늘에 새 떼와 초승달이 있다`,notInArt:[]},26:{scene:`흰 토끼가 구름 위에서 빛나는 검 한 자루를 높이 치켜든다. 뒤로 성과 초승달이 있다`,notInArt:[`구름에서 나온 손`,`검에 걸린 왕관`]},27:{scene:`눈가리개를 한 토끼가 돌 벤치에 앉아 검 두 자루를 가슴 앞에서 엇갈려 든다. 뒤로 바위섬이 솟은 바다와 초승달이 있다`,notInArt:[]},28:{scene:`검은 망토의 토끼가 비 내리는 얕은 물에 서서 눈물을 흘리며, 검 세 자루가 꿰뚫은 빛나는 하트를 가슴 앞에 안고 있다. 하늘에 먹구름이 끼어 있다`,notInArt:[]},29:{scene:`토끼가 돌 무덤 위에 두 손을 모으고 눈을 감은 채 누워 있고, 위 벽에 검 세 자루가 걸려 있으며 한 자루는 몸 옆에 놓여 있다. 옆에 스테인드글라스 창이 있다`,notInArt:[`무덤 위 기사 조각`]},30:{scene:`망토를 두른 토끼가 검 두 자루를 안고 서 있고, 옆 땅에 검 세 자루가 꽂혀 있다. 뒤로 두 인물이 바닷가 쪽으로 걸어가고, 하늘에 구름이 빠르게 흐른다`,notInArt:[]},31:{scene:`두건 망토의 토끼가 작은 토끼를 태운 나룻배에서 노를 젓고, 배 앞쪽에 검 여섯 자루가 꽂혀 있다. 안개 낀 물 건너편에 마을이 보이고 하늘에 초승달이 떠 있다`,notInArt:[]},32:{scene:`갈색 두건 옷의 토끼가 검 여러 자루를 끌어안은 채 걸어 나온다. 뒤로 줄무늬 천막들 앞 땅에 검 세 자루가 꽂혀 있고, 분홍빛 구름이 낀 하늘에 초승달이 떠 있다`,notInArt:[]},33:{scene:`눈가리개를 하고 몸이 천으로 칭칭 감긴 토끼가 땅에 꽂힌 검들 사이에 서 있다. 뒤로 바다와 성이 선 절벽, 초승달이 있다`,notInArt:[`물웅덩이`]},34:{scene:`토끼가 어두운 방 침대에 앉아 두 손으로 얼굴을 감싸고, 뒤 벽에 검들이 줄지어 걸려 있다. 창밖에 초승달이 떠 있다`,notInArt:[`장미 무늬 이불`]},35:{scene:`토끼가 땅에 엎드려 쓰러져 있고 등에 검 열 자루가 꽂혀 있다. 뒤로 먹구름 아래 바다 위로 노랗게 해가 떠오른다`,notInArt:[]},36:{scene:`왕관 쓴 검은 고양이 왕이 사자 조각이 선 돌 왕좌에 앉아 붉은 구슬 지팡이를 쥐고 있다. 뒤로 사막 마을, 발치 모래에 전갈과 도마뱀이 있다`,notInArt:[]},37:{scene:`왕관 쓴 검은 고양이 여왕이 청록 드레스를 입고 사자 조각 왕좌에 앉아 한 손에 붉은 구슬 지팡이, 다른 손에 해바라기를 든다. 뒤로 피라미드와 햇살이 있다`,notInArt:[`발치의 검은 고양이`]},38:{scene:`갑옷 입은 검은 고양이 기사가 붉은 구슬 지팡이를 들고 낙타를 타고 사막을 지난다`,notInArt:[`말`,`피라미드`]},39:{scene:`깃털 모자를 쓴 검은 고양이 시종이 모래 위에 서서 붉은 구슬 지팡이를 쥐고 있다. 뒤로 피라미드와 야자수 오아시스가 있다`,notInArt:[]},40:{scene:`검은 고양이가 사막 마을 앞 주황빛 하늘 아래에서 붉은 구슬 지팡이를 쥐고 서 있다. 지팡이에는 잎이 돋고 위로 불꽃이 피어오른다`,notInArt:[`구름에서 나온 손`]},41:{scene:`초록 망토의 검은 고양이가 성탑 위에서 한 손에 붉은 구슬 지팡이, 다른 손에 지구본을 들고 있고, 옆에 지팡이 하나가 세워져 있다. 아래로 바다와 해안, 하늘에 새들이 있다`,notInArt:[]},42:{scene:`망토를 두른 검은 고양이가 등을 보이며 바다 위 절벽에 서서 지팡이 하나를 쥐고, 옆에 지팡이 두 개가 꽂혀 있다. 해 지는 바다 위로 배들이 떠 간다`,notInArt:[`항구`]},43:{scene:`꽃 장식을 건 붉은 구슬 지팡이 네 개 아래에서 검은 고양이가 두 손을 들고 춤춘다. 양옆에서는 연한 털빛 고양이 둘이 꽃다발을 든 채 반긴다. 뒤로 사막 성이 있다`,notInArt:[]},44:{scene:`털빛이 다른 고양이 다섯이 사막에서 붉은 구슬 지팡이를 엇갈려 맞대며 겨룬다. 검은·회색·흰·주황 줄무늬·갈색 고양이이고, 뒤로 사막 마을이 있다`,notInArt:[]},45:{scene:`월계관을 쓴 초록 망토의 검은 고양이가 낙타를 타고 월계관을 건 지팡이를 들고 있고, 둘레에서 지팡이를 든 사람들이 반긴다. 하늘에 꽃종이가 날리고 깃발 장식이 걸려 있다`,notInArt:[`백마`]},46:{scene:`검은 고양이가 바위 언덕 꼭대기에서 지팡이를 세워 쥐고 서 있다. 아래에서 지팡이 여섯 개가 솟아 올라오고, 뒤로 사막 마을과 불꽃 같은 하늘이 있다`,notInArt:[`짝짝이 신발`]},47:{scene:`붉은 구슬이 달린 지팡이 여덟 개가 별 뜬 밤하늘을 가로질러 날아가고, 아래 언덕에서 검은 고양이가 그것을 올려다본다. 멀리 마을이 있다`,notInArt:[`강과 푸른 들판`]},48:{scene:`머리에 흰 붕대를 감은 검은 고양이가 지팡이 하나를 쥐고, 울타리처럼 늘어선 지팡이 여덟 개 앞에 서 있다. 멀리 사막 마을과 산이 있다`,notInArt:[]},49:{scene:`검은 고양이가 지팡이 묶음을 가슴과 어깨에 안고 사막 언덕을 힘겹게 오른다. 멀리 마을이 있다`,notInArt:[`푸른 들판`]},50:{scene:`왕관 쓴 호랑이 왕이 오각별 원반 장식이 달린 돌 왕좌에 앉아 새싹 화분을 들고 미소 짓는다. 둘레는 우거진 정글이다`,notInArt:[]},51:{scene:`왕관 쓴 호랑이 여왕이 초록 망토를 두르고 조각된 나무 왕좌에 앉아 새싹 화분을 안고 있다. 둘레에 장미 덩굴이 우거지고 뒤로 해가 빛난다`,notInArt:[]},52:{scene:`갑옷 입은 호랑이 기사가 코끼리를 탄 채 정글 속 고랑 진 흙길에 멈춰 서서 새싹 화분을 들고 있다`,notInArt:[`말`,`금화`]},53:{scene:`초록 베레모를 쓴 호랑이 시종이 정글 속 길에 서서 새싹 화분을 들고 있다. 뒤에 들꽃이 핀 풀밭이 있다`,notInArt:[`금화`]},54:{scene:`호랑이가 정글 길에서 새싹 화분을 들고 웃고 있다`,notInArt:[`구름에서 나온 손`,`금화`,`꽃 아치 정원`]},55:{scene:`호랑이가 정글 개울의 징검돌 위에서 양손에 화분을 하나씩 든 채 균형을 잡는다. 무한대 모양 금빛 끈이 두 화분을 감싸고, 뒤로 큰 물결이 인다`,notInArt:[`파도 위 배`]},56:{scene:`큰 호랑이가 돌 아치 아래 나무 작업대에서 새싹 화분 세 개를 돌보고, 양옆에서 작은 호랑이 둘이 물뿌리개와 씨앗 주머니를 들고 돕는다`,notInArt:[`금화`]},57:{scene:`초록 망토의 호랑이가 돌 벤치에 앉아 화분 두 개를 품에 꼭 끌어안고, 발치에 화분 두 개를 두고 있다. 뒤 나무 위에 집이 있고 해가 떠 있다`,notInArt:[`금화`,`도시`]},58:{scene:`해진 망토와 두건 차림의 호랑이 둘이 시무룩한 얼굴로 비 내리는 어두운 돌길을 걷는다. 옆의 환한 스테인드글라스 창가에 새싹 화분 다섯 개가 놓여 있다`,notInArt:[`눈`,`목발`]},59:{scene:`호랑이가 정원 분수 앞에서 다른 호랑이들에게 화분을 나눠 준다`,notInArt:[`저울`,`금화`,`구걸하는 사람`]},60:{scene:`멜빵바지를 입은 호랑이가 삽을 짚은 채 앞에 놓인 새싹 화분 일곱 개를 바라본다. 둘레는 우거진 정글이다`,notInArt:[`덤불에 열린 금화`]},61:{scene:`앞치마 두른 호랑이가 작업대 앞에서 모종삽으로 새싹 화분을 하나씩 손질하고, 선반과 작업대에 화분들이 놓여 있다`,notInArt:[`망치와 끌`,`금화`]},62:{scene:`흰 옷의 호랑이가 포도 덩굴이 드리운 기둥 정자에서 받침대 위 화분을 어루만지고, 다른 손에 작은 새가 앉아 있다. 둘레에 새싹 화분들이 놓여 있다`,notInArt:[`금화`]},63:{scene:`할아버지 호랑이부터 아이 호랑이까지 여러 세대 가족이 화분 열 개에 둘러싸여 다정하게 모여 있다`,notInArt:[`개`,`금화`]},64:{scene:`왕관 쓴 개구리 왕이 수련이 핀 물가 왕좌에 앉아 금잔을 든다`,notInArt:[`바다 위 왕좌`,`배`,`물고기`]},65:{scene:`왕관과 베일을 쓴 개구리 여왕이 물 위 커다란 조개껍데기 왕좌에 앉아 뚜껑 달린 금빛 성배를 두 손으로 든다. 둘레에 연꽃과 수련이 피어 있다`,notInArt:[`천사 장식 왕좌`]},66:{scene:`갑옷에 왕관 쓴 개구리 기사가 잔을 들고 노 젓는 배를 타고 야자수 물가를 지난다`,notInArt:[`백마`]},67:{scene:`붉은 망토의 개구리 시종이 수련잎 위에 서서 물고기가 든 금잔을 들고 있다`,notInArt:[`바다`]},68:{scene:`개구리가 물가에서 금잔을 높이 들고, 잔에서 물줄기가 연못으로 떨어진다. 뒤로 야자수가 있다`,notInArt:[`구름에서 나온 손`,`비둘기`,`다섯 물줄기`]},69:{scene:`개구리 둘이 수련잎 위에 서서 서로 잔을 맞대며 마주 보고, 위에 날개 달린 뱀 지팡이가 떠 있다`,notInArt:[`날개 달린 사자 머리`]},70:{scene:`개구리 셋이 야자수와 깃발 장식 아래 물가에서 잔 세 개를 높이 들고 건배한다`,notInArt:[`화관`,`과일`]},71:{scene:`개구리가 나무 아래 물가 바위에 시큰둥하게 앉아 있고, 앞에 잔 셋이 놓여 있으며 공중에 잔 하나가 떠 있다`,notInArt:[`구름에서 나온 손`]},72:{scene:`검은 망토의 개구리가 시무룩한 얼굴로 물가에 서 있고, 앞에 엎질러진 잔 세 개, 뒤쪽에 서 있는 잔 두 개가 있다. 멀리 돌다리가 강을 가로지른다`,notInArt:[`강 건너 성`]},73:{scene:`큰 개구리가 연꽃 핀 물가에서 작은 개구리에게 꽃 담긴 잔을 건네고, 앞에 꽃이 꽂힌 잔 다섯 개가 나란히 놓여 있다`,notInArt:[`마을 마당`]},74:{scene:`개구리가 수련잎 위에 앉아 한 손을 볼에 대고, 구름 속에 떠 있는 잔 일곱 개(별·왕관·보석·월계관·성·나비·용이 담긴 잔)를 바라본다`,notInArt:[`뱀`]},75:{scene:`갈색 망토를 두른 개구리가 지팡이를 짚은 채 등을 보이며 징검돌 쪽으로 걸어간다. 뒤에 남은 물가에 두 층으로 쌓인 잔 여덟 개가 있고, 하늘에 초승달이 뜨고 멀리 산이 있다`,notInArt:[]},76:{scene:`개구리가 팔짱을 낀 채 나무 벤치에 흐뭇하게 앉아 있다. 뒤 아치 모양 선반에 잔 아홉 개가 놓여 있다`,notInArt:[`푸른 휘장`]},77:{scene:`잔 열 개가 걸린 무지개 위로 웃는 해가 떠 있다. 아래 물가에 개구리 둘이 나란히 서 있고, 아이 개구리 둘이 수련잎 위에서 뛰논다`,notInArt:[`집`]}},Wt=4e3,Gt=3,Kt=`chinipy:tarot-readings-changed`,qt=new Map(i.map(e=>[e.id,e])),J